"""The climbing motion generated by placo [Ours]: the moving limb's route too, not only the body.

placo_ik.py follows ik.py's corridor for the moving ball. Here the ball only gets goals, and
placo's own features make the route between them:
- **goals**, each reached along a placo.CubicSpline3D from the last (at rest at both ends): out
  of socket a straight up by EXIT (the simulator's sockets let a ball out only within ~10 deg of
  vertical [simulator wall.py, EXIT_BLOCK]), to EXIT above socket b, then down into it;
- **collision avoidance** (placo's AvoidSelfCollisionsConstraint on the simulator's robot
  collision shapes, loaded from its MJCF): the moving limb's links (the forearm, or the shin, ankle
  and foot) keep MARGIN from the wall and from every hold near the route, each hold a box around
  its collision parts (HOLD_BOX, measured on the simulator's hold). So where the straight goal
  line passes a hold, placo bends the limb's path around it. Socket a's hold is ignored while the
  ball comes out of it, socket b's while it goes in;
- **the body**, as placo_ik: the held balls hard, the trunk and the hang posture soft, joint and
  speed limits, and settling on b's sockets after the ball is in.
Stance poses are placo_ik's (the same robot: its MJCF and URDF frames agree to 1e-9 m). Output
in ik.model's configuration layout, as placo_ik. Imported by scripts/placo_trajectory.py only.
"""

import json
import os
import tempfile

import microban_model
import microban_sim
import mujoco
import numpy as np
import pinocchio as pin
import placo

from rcr.kinematics import ik, placo_ik, validate_plan
from rcr.types import LIMBS, MICROBAN_JOINTS, ContactPlan, Stance, Trajectory, WallModel

EXIT = 0.04  # [m] straight up out of socket a; also above socket b before going in [Ours]
EXIT_TIME, TRANSFER_TIME, ENTER_TIME = 0.4, 1.2, 0.4  # [s] the three goals' splines [Ours]
MARGIN = 0.008  # [m] the moving limb's links from the wall and the holds [Ours]
# while going across, a soft pull of the moving ball out to AWAY in front of the wall face (its
# y), weight AWAY_WEIGHT against the goal's MOVING_WEIGHT: a preference, the goal and the
# collisions still make the route. Without it a goal straight behind a hold stopped the limb
# against it (placo's solver looks one step ahead [placo docs, collisions]): 2 of 5 N1 moves
# ended 38 mm short [Ours]
AWAY, AWAY_WEIGHT = 0.07, 1e3  # [m] the holds reach 43 mm out of the wall face
TRIGGER = 0.03  # [m] pairs closer than this enter the QP [placo's self_collisions_trigger]
COLLISION_WEIGHT = 1e4  # soft: a start already within MARGIN of the wall stays solvable [Ours]
NEAR = 0.25  # [m] holds this close to the segment a -> b are obstacles
ENVIRONMENT = "environment"  # the body that carries the wall and the holds (Scene)
ORIGIN = "environment_origin"  # a site at its origin
ENV_SLIDES = ("environment_x", "environment_y", "environment_z")  # its joints
ENV_HINGES = ("environment_rx", "environment_ry", "environment_rz")
# a hold's collision parts (hull, skin and cup spheres [simulator scene.py]) fit in this box, from
# its socket centre [m]: x -20.4..20.6, y -18.8..31.3, z -18.8..18.0 mm
HOLD_CENTRE = np.array([0.0001, 0.00625, -0.0004])
HOLD_HALF = np.array([0.0205, 0.02505, 0.0184])
# the moving limb's links: those moved by these joints
LIMB_JOINTS = {
    "right_hand": ("right_elbow",),
    "left_hand": ("left_elbow",),
    "right_foot": ("right_knee", "right_ankle_pitch", "right_ankle_roll"),
    "left_foot": ("left_knee", "left_ankle_pitch", "left_ankle_roll"),
}


class Scene:
    """placo on the simulator's robot with the wall and a box per hold, and its solver."""

    def __init__(self, sim_wall):
        from climbing_sim.scene import WALL_HEIGHT, WALL_THICKNESS, WALL_WIDTH

        spec = microban_sim.build_spec("climber")
        box = mujoco.mjtGeom.mjGEOM_BOX
        # placo's MJCF loader reads only the first body tree, the robot's, and its collision model
        # can't be extended: the wall and the holds are shapes of a body inside that tree, which
        # a hard frame task keeps at the world's origin (set_q places it there). Its joints: three
        # slides then three hinges about x, y, z (no range: placo leaves them unlimited); a
        # nested free joint gets placo's position limits of +-1.01, less than the trunk's height
        # up the wall, and placo's MJCF loader has no ball joint.
        env = spec.worldbody.first_body().add_body(name=ENVIRONMENT)
        for axis, name in zip(np.eye(3), ENV_SLIDES, strict=True):
            env.add_joint(name=name, type=mujoco.mjtJoint.mjJNT_SLIDE, axis=axis.tolist())
        for axis, name in zip(np.eye(3), ENV_HINGES, strict=True):
            env.add_joint(name=name, type=mujoco.mjtJoint.mjJNT_HINGE, axis=axis.tolist())
        env.add_site(name=ORIGIN)  # a frame of its own, for the frame task
        env.add_geom(
            name="wall",
            type=box,
            mass=1e-6,
            size=[WALL_WIDTH / 2, WALL_THICKNESS / 2, WALL_HEIGHT / 2],
            pos=[WALL_WIDTH / 2, WALL_THICKNESS / 2, WALL_HEIGHT / 2],
        )
        for h in sim_wall.holds:
            env.add_geom(name=f"hold_r{h.row}_c{h.col}", type=box, mass=1e-6,
                         size=HOLD_HALF.tolist(),
                         pos=(np.array(h.socket) + HOLD_CENTRE).tolist())  # fmt: skip
        assets = os.path.join(os.path.dirname(microban_model.__file__), "mjcf", "assets")
        xml = spec.to_xml().replace('meshdir="assets"', f'meshdir="{assets}"')
        self.dir = tempfile.mkdtemp(prefix="placo_scene_")
        path = os.path.join(self.dir, "scene.xml")
        with open(path, "w") as f:
            f.write(xml)
        self.robot = robot = placo.RobotWrapper(path, placo.Flags.mjcf)
        model, objects = robot.model, list(robot.collision_model.geometryObjects)
        # each moving limb's collision shapes (indices), and the environment's by name
        self.links = {
            limb: [
                k
                for k, o in enumerate(objects)
                if model.names[model.frames[o.parentFrame].parentJoint] in joints
            ]
            for limb, joints in LIMB_JOINTS.items()
        }
        # placo names a shape after its body: the environment's come in the order added
        env_shapes = [
            k for k, o in enumerate(objects) if model.frames[o.parentFrame].name == ENVIRONMENT
        ]
        names = ["wall", *(f"hold_r{h.row}_c{h.col}" for h in sim_wall.holds)]
        self.shapes = dict(zip(names, env_shapes, strict=True))
        assert all(self.links.values()) and "wall" in self.shapes, (self.links, list(self.shapes))
        self.env_offset = robot.get_joint_offset(f"Composite_{ENV_SLIDES[0]}")
        # its six coordinates only cancel the trunk's motion: no speed limit (the MJCF has none,
        # which placo reads as 0, and the speed limits then fail the hard frame task)
        v = robot.get_joint_v_offset(f"Composite_{ENV_SLIDES[0]}")
        model.velocityLimit[v : v + 6] = 1e3  # placo's own model (robot.model is a reference)
        # the motors' speed limits are the URDF's (6.6 rad/s): the MJCF has none, which is
        # infinite in placo and makes the QP's bounds infinite
        for name in MICROBAN_JOINTS:
            model.velocityLimit[robot.get_joint_v_offset(name)] = ik.SPEED_LIMIT[
                ik.model.idx_vs[ik.model.getJointId(name)] - 6
            ]
        assert np.isfinite(robot.model.velocityLimit[6:]).all(), "speed limits not set"
        self.socket = {f"r{h.row}_c{h.col}": np.array(h.socket) for h in sim_wall.holds}
        self.joint_index = {n: ik.model.idx_qs[ik.model.getJointId(n)] for n in MICROBAN_JOINTS}

        self.solver = solver = placo.KinematicsSolver(robot)
        solver.mask_fbase(False)
        solver.enable_joint_limits(True)
        self.balls = {limb: solver.add_position_task(f"{limb}_ball", np.zeros(3)) for limb in LIMBS}
        trunk = solver.add_orientation_task("trunk", ik.TRUNK_UPRIGHT)
        trunk.configure("trunk", "soft", placo_ik.TRUNK_WEIGHT)
        self.height = solver.add_position_task("trunk", np.zeros(3))
        self.height.mask.set_axises("z")
        self.height.configure("height", "soft", placo_ik.TRUNK_WEIGHT)
        posture = solver.add_joints_task()
        posture.set_joints({n: float(ik.Q_HANG[j]) for n, j in self.joint_index.items()})
        posture.configure("posture", "soft", placo_ik.POSTURE_WEIGHT)
        solver.add_frame_task(ORIGIN, np.eye(4)).configure(ENVIRONMENT, "hard", 1.0, 1.0)
        self.collisions = solver.add_avoid_self_collisions_constraint()
        self.collisions.self_collisions_margin = MARGIN
        self.collisions.self_collisions_trigger = TRIGGER
        self.collisions.configure("collisions", "soft", COLLISION_WEIGHT)

    def avoid(self, limb: str, holds: list[str]) -> None:
        """Collision pairs: the moving limb's links against the wall and these holds."""
        others = [self.shapes["wall"], *(self.shapes[f"hold_{h}"] for h in holds)]
        pairs = [[link, other] for link in self.links[limb] for other in others]
        path = os.path.join(self.dir, "pairs.json")
        with open(path, "w") as f:
            json.dump(pairs, f)
        self.robot.load_collision_pairs(path)

    def set_q(self, q: np.ndarray) -> None:
        """placo's state from a configuration in ik.model's layout."""
        state = self.robot.state.q.copy()
        state[0:7] = q[0:7]  # the free flyer: the same in both
        self.robot.state.q = state
        for name, j in self.joint_index.items():
            self.robot.set_joint(name, float(q[j]))
        self.robot.update_kinematics()
        # the environment at the world's origin: its joint, relative to the trunk, the inverse
        inverse = np.linalg.inv(self.robot.get_T_world_frame("trunk"))
        R = inverse[:3, :3]  # = Rx(a) Ry(b) Rz(c), the hinges in order; b near 0 (trunk upright)
        angles = (np.arctan2(-R[1, 2], R[2, 2]), np.arcsin(np.clip(R[0, 2], -1, 1)),
                  np.arctan2(-R[0, 1], R[0, 0]))  # fmt: skip
        state = self.robot.state.q.copy()  # placo merges the six into one composite joint
        state[self.env_offset : self.env_offset + 6] = [*inverse[:3, 3], *angles]
        self.robot.state.q = state
        self.robot.state.qd = np.zeros(len(self.robot.state.qd))
        self.robot.update_kinematics()

    def get_q(self) -> np.ndarray:
        """placo's state in ik.model's layout."""
        q = ik.Q_HANG.copy()
        q[0:7] = self.robot.state.q[0:7]
        for name, j in self.joint_index.items():
            q[j] = self.robot.get_joint(name)
        return q

    def step(self, targets: np.ndarray, moving: str | None) -> np.ndarray:
        """placo_ik.ITERATIONS solves toward the balls' targets; the configuration after."""
        for limb, target in zip(LIMBS, targets, strict=True):
            self.balls[limb].target_world = target
            hard = limb != moving
            self.balls[limb].configure(
                limb, "hard" if hard else "soft", 1.0 if hard else placo_ik.MOVING_WEIGHT
            )
        self.height.target_world = np.array([0.0, 0.0, targets[:, 2].mean() + ik.TRUNK_HEIGHT])
        for _ in range(placo_ik.ITERATIONS):
            self.robot.update_kinematics()
            self.solver.solve(True)
        self.robot.update_kinematics()
        return self.get_q()

    def clearance(self) -> float:
        """[m] the smallest distance of the active collision pairs now."""
        distances = self.robot.distances()
        return min((d.min_distance for d in distances), default=float("inf"))


_scenes = {}  # wall id -> Scene


def scene(wall: WallModel, sim_wall) -> Scene:
    if wall.id not in _scenes:
        _scenes[wall.id] = Scene(sim_wall)
    return _scenes[wall.id]


def near(scene: Scene, a: np.ndarray, b: np.ndarray, skip: set) -> list[str]:
    """The holds within NEAR of the segment a -> b, but those in skip."""
    out = []
    for hold, p in scene.socket.items():
        s = np.clip(np.dot(p - a, b - a) / max(np.dot(b - a, b - a), 1e-12), 0.0, 1.0)
        if hold not in skip and np.linalg.norm(p - (a + s * (b - a))) < NEAR:
            out.append(hold)
    return out


def generate_move(wall: WallModel, sim_wall, a: Stance, b: Stance, q0: np.ndarray):
    """The configurations of the move a -> b, one every ik.DT from q0 (excluded), the moving
    ball's route made by placo (see the module): its goals along splines, its links kept off the
    wall and the nearby holds. Then settling on b's sockets and ik.WAIT_TIME holding still. Also
    the smallest clearance of the moving limb's links [m] on the way. ValueError, naming the move,
    if the solver fails or a held ball gets ik.MAX_ERROR from its socket."""
    sc = scene(wall, sim_wall)
    limb = ik.moving_limb(a, b)
    move = f"{limb} {a.contacts[limb]} -> {b.contacts[limb]}"
    i = LIMBS.index(limb)
    held, end = ik.sockets(wall, a), ik.sockets(wall, b)
    start = held[i]
    up = np.array([0.0, 0.0, EXIT])
    source, target = a.contacts[limb], b.contacts[limb]
    others = near(sc, start, end[i], {source, target})
    phases = [  # (goal, duration, holds to avoid, pulled away from the wall)
        (start + up, EXIT_TIME, others, False),
        (end[i] + up, TRANSFER_TIME, [*others, source, target], True),
        (end[i], ENTER_TIME, [*others, source], False),
    ]
    sc.set_q(q0)
    sc.solver.enable_velocity_limits(True)
    sc.solver.dt = ik.DT / placo_ik.ITERATIONS
    q, out, clearance, position = q0, [], float("inf"), start
    for goal, duration, avoid, away in phases:
        sc.avoid(limb, avoid)
        pull = None
        if away:
            pull = sc.solver.add_position_task(f"{limb}_ball", np.array([0.0, -AWAY, 0.0]))
            pull.mask.set_axises("y")
            pull.configure("away", "soft", AWAY_WEIGHT)
        spline = placo.CubicSpline3D()
        spline.add_point(0.0, position, np.zeros(3))
        spline.add_point(duration, goal, np.zeros(3))
        for k in range(1, round(duration / ik.DT) + 1):
            targets = held.copy()
            targets[i] = spline.pos(k * ik.DT)
            try:
                q = sc.step(targets, limb)
            except RuntimeError as e:
                raise ValueError(f"{move}: placo failed ({e})") from e
            error = np.linalg.norm(targets - ik.balls(q), axis=1)
            if not np.delete(error, i).max() <= ik.MAX_ERROR:
                e = np.delete(error, i).max() * 1000
                raise ValueError(f"{move}: a held ball {e:.0f} mm from its socket")
            clearance = min(clearance, sc.clearance())
            out.append(q)
        if pull is not None:
            sc.solver.remove_task(pull)
        position = goal
    # settle on b's sockets; the moving ball stays soft (pulled in with MOVING_WEIGHT): hard, a
    # ball not quite in yet made the QP infeasible within the speed limits
    sc.avoid(limb, others)
    for _ in range(round(placo_ik.SETTLE_TIME / ik.DT)):
        try:
            new = sc.step(end, limb)
        except RuntimeError as e:
            raise ValueError(f"{move}: placo failed settling ({e})") from e
        settled = np.linalg.norm(pin.difference(ik.model, q, new)) < ik.SETTLED
        q = new
        out.append(q)
        if settled:
            break
    out += [q] * round(ik.WAIT_TIME / ik.DT)
    return out, clearance


def optimise(wall: WallModel, sim_wall, plan: ContactPlan) -> Trajectory:
    """The full joint trajectory for this plan, every move's route generated by placo."""
    validate_plan(wall, plan)
    qs = [placo_ik.stance_pose(wall, plan.stances[0])]
    for a, b in zip(plan.stances, plan.stances[1:], strict=False):
        qs += generate_move(wall, sim_wall, a, b, qs[-1])[0]
    joints = [ik.model.idx_qs[ik.model.getJointId(name)] for name in MICROBAN_JOINTS]
    positions = [[float(q[j]) for j in joints] for q in qs]
    return Trajectory(
        joint_names=list(MICROBAN_JOINTS),
        times=[round(k * ik.DT, 9) for k in range(len(qs))],
        positions=positions,
        planned_positions=[row.copy() for row in positions],
        trunk_poses=[[float(v) for v in q[[0, 1, 2, 6, 3, 4, 5]]] for q in qs],
    )
